import { useMemo, useState } from 'react'
import { BookOpen, Check, ChevronDown, ChevronUp, Code2, Search, Sparkles } from 'lucide-react'
import './InterviewPrep.css'
import { pythonInterviewQuestions } from './pythonInterviewQuestions.js'
import { courseInterviewQuestions } from './courseInterviewQuestions.js'

const baseQuestions = [
  { id:1, topic:'Python', level:'Basic', title:'What is the difference between a list and a tuple?', prompt:'Explain mutability and show when you would use each.', answer:'A list is ordered and mutable, so you can add, remove, or replace items. A tuple is ordered but immutable after creation. Use lists for collections that change and tuples for fixed records or values that should not be reassigned.', syntax:`skills = ["Python", "SQL"]
skills.append("Django")
print(skills)

point = (10, 20)
print(point[0])
# point[0] = 99  # TypeError: tuples are immutable`, output:'[\'Python\', \'SQL\', \'Django\']\n10', tip:'Mention both the behavior and the reason you would choose one. A tuple is not automatically faster in every real-world use case.' },
  { id:2, topic:'Python', level:'Basic', title:'How do dictionaries handle duplicate keys?', prompt:'What happens if the same key is assigned twice?', answer:'Dictionary keys are unique. If the same key is written more than once, the later assignment replaces the earlier value; it does not create a second entry.', syntax:`candidate = {"name": "Asha", "score": 70}
candidate["score"] = 92
print(candidate)
# {'name': 'Asha', 'score': 92}`, output:"{'name': 'Asha', 'score': 92}", tip:'Keys must be hashable. Common key types include strings, numbers and tuples containing hashable values.' },
  { id:3, topic:'Python', level:'Basic', title:'What is the difference between == and is?', prompt:'Explain value equality versus object identity.', answer:'== compares values for equality. is checks whether two references point to the very same object. Use == for normal value comparisons; use is None when checking for None.', syntax:`first = [1, 2]
second = [1, 2]
third = first

print(first == second)  # True
print(first is second)  # False
print(first is third)   # True

value = None
if value is None:
    print("No value")`, output:'True\nFalse\nTrue\nNo value', tip:'Do not use is to compare strings or numbers by value. Object interning can make such tests misleading.' },
  { id:4, topic:'Python', level:'Intermediate', title:'What is a mutable default argument pitfall?', prompt:'Why can a default list retain data across function calls?', answer:'Default argument expressions are evaluated once when the function is defined, not every time it is called. A mutable default such as [] can therefore be shared by calls. Use None and create a new list inside the function.', syntax:`def add_item(item, items=None):
    if items is None:
        items = []
    items.append(item)
    return items

print(add_item("Python"))  # ['Python']
print(add_item("SQL"))     # ['SQL']`, output:"['Python']\n['SQL']", tip:'This question tests Python object lifetime and whether you understand when function defaults are evaluated.' },
  { id:5, topic:'Python', level:'Intermediate', title:'What are generators and yield?', prompt:'How do generators help process large datasets?', answer:'A generator produces values lazily, one at a time, and pauses at yield while preserving its local state. This can reduce memory use when processing large files or streams because you do not need to build the entire result list first.', syntax:`def squares(limit):
    for number in range(limit):
        yield number * number

for value in squares(4):
    print(value)`, output:'0\n1\n4\n9', tip:'Contrast yield with return: return exits the function, while yield produces a value and suspends the generator for later resumption.' },
  { id:6, topic:'Python', level:'Intermediate', title:'What is a decorator?', prompt:'Describe the wrapper pattern and a backend use case.', answer:'A decorator takes a function and returns another callable that adds behavior around it. Common backend uses include logging, timing, authorization checks, caching and retry logic. functools.wraps preserves useful metadata from the original function.', syntax:`from functools import wraps

def log_call(function):
    @wraps(function)
    def wrapper(*args, **kwargs):
        print(f"Calling {function.__name__}")
        return function(*args, **kwargs)
    return wrapper

@log_call
def greet(name):
    return f"Hello, {name}"

print(greet("Asha"))`, output:'Calling greet\nHello, Asha', tip:'Explain that @log_call is equivalent to greet = log_call(greet), and mention why returning the wrapped function matters.' },
  { id:7, topic:'Python', level:'Advanced', title:'What is the GIL, and how do threads differ from processes?', prompt:'Choose a concurrency approach for I/O-bound and CPU-bound work.', answer:'In standard CPython builds, the Global Interpreter Lock generally allows only one thread at a time to execute Python bytecode in a process. Threads are often effective for I/O-bound work because they can wait concurrently. Processes can use multiple CPU cores for CPU-bound Python work but add startup and communication overhead. Exact behavior depends on the Python build and workload.', syntax:`from concurrent.futures import ThreadPoolExecutor

def fetch_label(item):
    # Represents waiting for an I/O operation
    return f"loaded:{item}"

with ThreadPoolExecutor(max_workers=4) as pool:
    results = list(pool.map(fetch_label, ["a", "b", "c"]))
print(results)`, output:"['loaded:a', 'loaded:b', 'loaded:c']", tip:'Do not say threads are always faster. Discuss workload, network/database waiting, CPU cost and coordination overhead.' },
  { id:8, topic:'SQL', level:'Basic', title:'What is the difference between WHERE and HAVING?', prompt:'When does each clause filter data?', answer:'WHERE filters individual rows before grouping. HAVING filters groups after GROUP BY and is commonly used with aggregate conditions.', syntax:`SELECT department_id, COUNT(*) AS team_size
FROM employees
WHERE active = 1
GROUP BY department_id
HAVING COUNT(*) >= 5
ORDER BY team_size DESC;`, output:'Returns active employees grouped by department, showing only departments with at least five active employees.', tip:'The logical processing order is approximately FROM/JOIN, WHERE, GROUP BY, HAVING, SELECT, ORDER BY.' },
  { id:9, topic:'SQL', level:'Basic', title:'What is the difference between INNER JOIN and LEFT JOIN?', prompt:'Explain what happens when a row has no match.', answer:'INNER JOIN returns only rows that match the join condition in both tables. LEFT JOIN keeps every row from the left table and fills right-side columns with NULL when there is no match.', syntax:`SELECT c.name, d.name AS department
FROM candidates c
LEFT JOIN departments d
  ON d.id = c.department_id;`, output:'Candidates without a matching department still appear; their department value is NULL.', tip:'A condition on the right table in WHERE can unintentionally remove NULL rows and make a LEFT JOIN behave like an INNER JOIN.' },
  { id:10, topic:'SQL', level:'Intermediate', title:'How do you find the second-highest salary?', prompt:'Write a query that handles duplicate salary values.', answer:'Use a distinct salary ranking or the maximum salary below the maximum. The subquery below returns the second-highest distinct salary and returns no row if no second distinct salary exists.', syntax:`SELECT MAX(salary) AS second_highest_salary
FROM employees
WHERE salary < (SELECT MAX(salary) FROM employees);`, output:'One row containing the second-highest distinct salary, or NULL if there is no lower salary.', tip:'Clarify whether the interviewer means the second row after sorting or the second distinct salary. Those are different requirements.' },
  { id:11, topic:'SQL', level:'Advanced', title:'What is an index? What are its trade-offs?', prompt:'How can indexes help and hurt performance?', answer:'An index is an auxiliary data structure that helps the database locate rows without scanning the whole table in many queries. Indexes can improve filters, joins and ordering, but consume storage and add overhead to inserts, updates and deletes. The optimizer and data distribution determine whether an index is used.', syntax:`CREATE INDEX idx_employees_department
ON employees(department_id);

EXPLAIN
SELECT id, name
FROM employees
WHERE department_id = 10;`, output:'The query plan helps determine whether the database uses the index and how much work the query performs. EXPLAIN syntax varies by database.', tip:'Avoid recommending indexes blindly. Inspect the execution plan and consider selectivity, composite-index column order and write volume.' },
  { id:12, topic:'REST APIs', level:'Basic', title:'Explain common HTTP methods and status codes.', prompt:'Which method would you use to read, create, update or delete a resource?', answer:'GET retrieves a representation; POST commonly creates a resource or triggers processing; PUT replaces a resource representation; PATCH applies a partial update; DELETE removes a resource. Typical responses include 200 OK, 201 Created, 204 No Content, 400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found and 500 Internal Server Error.', syntax:`GET    /api/candidates/42  -> 200 OK
POST   /api/candidates      -> 201 Created
PATCH  /api/candidates/42  -> 200 OK
DELETE /api/candidates/42  -> 204 No Content`, output:'Choose the status code based on what happened; a successful DELETE can return 204 with no response body.', tip:'401 means valid authentication is missing or failed; 403 means the server understood the request but refuses access.' },
  { id:13, topic:'REST APIs', level:'Intermediate', title:'What makes an HTTP method idempotent?', prompt:'Why is idempotency important for retries?', answer:'An operation is idempotent when repeating the same request has the same intended effect as performing it once. GET, PUT and DELETE are defined as idempotent in HTTP semantics, although responses can differ. POST is not inherently idempotent; APIs can support safe retries with idempotency keys for operations such as payments.', syntax:`PUT /api/profiles/42
Content-Type: application/json

{"display_name": "Asha"}`, output:'Sending the same PUT repeatedly leaves the profile with the same intended representation.', tip:'Idempotent does not mean the response body or status must be identical on every request.' },
  { id:14, topic:'REST APIs', level:'Intermediate', title:'How should an API validate input and return errors?', prompt:'Show a consistent error response for invalid data.', answer:'Validate untrusted input at the API boundary, return an appropriate 4xx status for client mistakes, and use a stable error schema with a machine-readable code and a helpful message. Avoid returning stack traces or secrets to clients.', syntax:`HTTP/1.1 400 Bad Request
Content-Type: application/json

{
  "error": {
    "code": "VALIDATION_ERROR",
    "message": "score must be between 0 and 100",
    "field": "score"
  }
}`, output:'Clients can identify the invalid field and display a useful message without parsing a stack trace.', tip:'Use 401 for authentication failure, 403 for insufficient permission, 404 for missing resources and 500 for unexpected server failures.' },
  { id:15, topic:'REST APIs', level:'Advanced', title:'Authentication vs authorization: what is the difference?', prompt:'How do you protect an API endpoint?', answer:'Authentication establishes who the caller is. Authorization checks what that identity is allowed to do. A secure API validates tokens, enforces permissions on every protected action, uses TLS, limits request rates, protects secrets and avoids logging credentials.', syntax:`Request
  -> HTTPS/TLS
  -> Validate identity/token
  -> Check role and resource permission
  -> Apply rate limits
  -> Execute handler
  -> Log safe audit metadata`, output:'A caller with a valid identity but insufficient permission should generally receive 403 Forbidden.', tip:'Never trust a user ID or role supplied only in the request body. Derive identity from verified credentials and check access to the specific resource.' },

  { id:16, topic:'Python', level:'Basic', title:'How do *args and **kwargs work?', prompt:'How can a function accept a variable number of arguments?', answer:'*args collects extra positional arguments into a tuple. **kwargs collects extra keyword arguments into a dictionary. They are useful for flexible wrappers and APIs, but explicit parameters are clearer when the expected inputs are known.', syntax:`def show_profile(name, *skills, **details):
    print(name)
    print(skills)
    print(details)

show_profile("Asha", "Python", "SQL", city="Bengaluru")`, output:"Asha\n('Python', 'SQL')\n{'city': 'Bengaluru'}", tip:'Remember the difference: *args is positional and **kwargs is keyword-based.' },
  { id:17, topic:'Python', level:'Intermediate', title:'What is the difference between shallow and deep copy?', prompt:'What happens when a nested list is copied?', answer:'A shallow copy creates a new outer container but keeps references to nested objects. A deep copy recursively copies nested objects. Use copy.copy for shallow copies and copy.deepcopy when independent nested structures are required.', syntax:`import copy

original = [[1, 2], [3, 4]]
shallow = copy.copy(original)
deep = copy.deepcopy(original)
original[0].append(99)

print(shallow)  # [[1, 2, 99], [3, 4]]
print(deep)     # [[1, 2], [3, 4]]`, output:'The shallow copy reflects the nested-list change; the deep copy does not.', tip:'A shallow copy is often sufficient for flat collections. Deep copying can be expensive and may not be suitable for every object.' },
  { id:18, topic:'Python', level:'Advanced', title:'How do you handle exceptions in production code?', prompt:'Explain try, except, else and finally.', answer:'Put risky operations in try, catch expected exception types in except, use else for work that should run only when no exception occurred, and use finally for cleanup that must happen either way. Log enough context to debug without exposing secrets.', syntax:`try:
    number = int("42")
except ValueError:
    print("Invalid number")
else:
    print("Parsed:", number)
finally:
    print("Finished")`, output:'Parsed: 42\nFinished', tip:'Avoid broad except blocks that silently hide bugs. Raise or translate errors when the caller needs to handle them.' },
  { id:19, topic:'SQL', level:'Basic', title:'What is the difference between PRIMARY KEY and UNIQUE?', prompt:'How do these constraints protect data?', answer:'A primary key uniquely identifies each row and cannot be NULL. A table has one primary-key constraint, which may include multiple columns. UNIQUE prevents duplicate values for a column or column combination; NULL handling for UNIQUE varies by database.', syntax:`CREATE TABLE departments (
  id INT PRIMARY KEY,
  name VARCHAR(100) UNIQUE
);`, output:'Duplicate department IDs are rejected, and duplicate non-NULL department names are rejected by this example.', tip:'Mention that exact NULL behavior for UNIQUE constraints depends on the database engine.' },
  { id:20, topic:'SQL', level:'Intermediate', title:'What is a CTE, and when would you use one?', prompt:'Show how WITH can make a query easier to read.', answer:'A common table expression (CTE) names a query result for use by the following statement. It can make complex queries easier to read and can support recursive queries in databases that implement recursive CTEs. A CTE is not automatically faster than a subquery.', syntax:`WITH high_scores AS (
  SELECT id, name, score
  FROM candidates
  WHERE score >= 80
)
SELECT name, score
FROM high_scores
ORDER BY score DESC;`, output:'Returns candidates with scores of at least 80, ordered from highest to lowest.', tip:'Use a CTE to improve readability, then check the query plan if performance matters.' },
  { id:21, topic:'SQL', level:'Advanced', title:'What are transactions and ACID properties?', prompt:'Why use a transaction for related updates?', answer:'A transaction groups changes into a single logical unit. ACID means Atomicity (all or nothing), Consistency (valid rules remain satisfied), Isolation (concurrent work is controlled), and Durability (committed changes persist). Roll back when part of the operation fails.', syntax:`BEGIN TRANSACTION;

UPDATE accounts
SET balance = balance - 100
WHERE id = 1;

UPDATE accounts
SET balance = balance + 100
WHERE id = 2;

COMMIT;`, output:'Both updates commit together if successful. Application code should roll back on failure; transaction syntax differs by database.', tip:'Discuss isolation levels and deadlocks when the interviewer asks about concurrent transactions.' },
  { id:22, topic:'REST APIs', level:'Basic', title:'What is REST, and what is a resource?', prompt:'How would you model a simple candidates endpoint?', answer:'REST is an architectural style that treats data and functionality as resources identified by URLs and manipulated through standard HTTP semantics. A resource URL should represent a thing, usually using nouns, while the HTTP method describes the operation.', syntax:`GET    /api/candidates
GET    /api/candidates/42
POST   /api/candidates
PATCH  /api/candidates/42
DELETE /api/candidates/42`, output:'The collection is /api/candidates and an individual candidate is /api/candidates/42.', tip:'Keep resource paths consistent and avoid embedding action verbs in every URL when an HTTP method expresses the action.' },
  { id:23, topic:'REST APIs', level:'Intermediate', title:'How should pagination be designed?', prompt:'Why should an API avoid returning an unbounded collection?', answer:'Pagination limits response size and reduces memory, network and database load. Offset/limit pagination is simple, while cursor pagination is often more stable for frequently changing or very large datasets. Enforce a maximum page size and return a continuation indicator.', syntax:`{
  "results": [{"id": 41}, {"id": 42}],
  "limit": 2,
  "next_cursor": "eyJpZCI6NDJ9"
}`, output:'The client requests the next page using the returned cursor when one is available.', tip:'Use a deterministic sort order. Offset pagination can skip or repeat rows when data changes between requests.' },
  { id:24, topic:'REST APIs', level:'Advanced', title:'How do you design safe retries for a payment API?', prompt:'What problem does an idempotency key solve?', answer:'A client may retry after a timeout without knowing whether the server processed the first request. An idempotency key lets the server associate retries with the original operation and return the stored result rather than charging twice. Store keys safely with appropriate scope and expiration.', syntax:`POST /api/payments
Idempotency-Key: order-8472-attempt-1
Content-Type: application/json

{"order_id": 8472, "amount": 1250}`, output:'Repeated requests using the same key and same operation should not create duplicate charges.', tip:'Define behavior for key reuse with a different payload, concurrent requests, key retention and failed operations.' },
]

const additionalQuestions = [
  { topic:'Java', level:'Basic', title:'What are the four pillars of OOP?', prompt:'Explain encapsulation, abstraction, inheritance and polymorphism.', answer:'Encapsulation protects state behind a clear API; abstraction exposes essential behavior; inheritance reuses or specializes a type; polymorphism lets callers use a common contract with different implementations.', syntax:`interface Notifier { void send(String message); }
class EmailNotifier implements Notifier {
    public void send(String message) { System.out.println(message); }
}
Notifier notifier = new EmailNotifier();
notifier.send("Hello");`, output:'Prints Hello. The variable uses the interface while the object supplies the implementation.', tip:'Give a real example and distinguish inheritance (“is-a”) from composition (“has-a”).' },
  { topic:'Java', level:'Intermediate', title:'When would you use a List, Set or Map?', prompt:'Choose a collection for ordered values, unique values and key lookup.', answer:'List preserves positional order and permits duplicates; Set models uniqueness; Map associates unique keys with values. Choose based on required semantics, then consider complexity and implementation.', syntax:`List<String> names = new ArrayList<>();
names.add("Asha");
Set<String> unique = new HashSet<>(names);
Map<String, Integer> scores = new HashMap<>();
scores.put("Asha", 90);`, output:'names contains Asha, unique contains one Asha, and scores maps Asha to 90.', tip:'Mention that HashMap does not promise sorted key order; use a suitable implementation when order matters.' },
  { topic:'Java', level:'Advanced', title:'How does the Java Stream API work?', prompt:'Describe a pipeline and the difference between intermediate and terminal operations.', answer:'A stream pipeline starts from a source, applies lazy intermediate operations such as filter and map, and finishes with a terminal operation such as collect or count. Streams do not store data themselves.', syntax:`List<Integer> values = List.of(2, 5, 8, 9);
List<Integer> evenSquares = values.stream()
    .filter(n -> n % 2 == 0)
    .map(n -> n * n)
    .toList();
System.out.println(evenSquares);`, output:'[4, 64]', tip:'Avoid side effects in stream operations and do not assume parallel streams are automatically faster.' },
  { topic:'JavaScript', level:'Basic', title:'What is the difference between let, const and var?', prompt:'Explain scope, reassignment and redeclaration.', answer:'let and const are block-scoped. let can be reassigned; const cannot be reassigned, though an object stored in a const binding can still be mutated. var is function-scoped and has older hoisting behavior.', syntax:`const profile = { name: "Asha" };
profile.name = "Ravi"; // allowed
let count = 1;
count += 1;
console.log(profile.name, count);`, output:'Ravi 2', tip:'Prefer const by default, let when reassignment is needed, and avoid var in modern code.' },
  { topic:'JavaScript', level:'Intermediate', title:'How do promises and async/await work?', prompt:'Show how asynchronous work can be awaited and errors handled.', answer:'A Promise represents an eventual result. async functions return promises; await pauses that function until a promise settles. try/catch handles rejected operations when awaited inside the block.', syntax:`async function loadUser() {
  try {
    const response = await fetch("/api/users/1");
    if (!response.ok) throw new Error("Request failed");
    return await response.json();
  } catch (error) {
    console.error(error.message);
    throw error;
  }
}`, output:'Returns parsed user data on success; logs and rethrows a failure.', tip:'Check response.ok—fetch does not reject automatically for HTTP 404 or 500 responses.' },
  { topic:'JavaScript', level:'Advanced', title:'Explain the event loop and microtasks.', prompt:'Why can a Promise callback run before setTimeout(..., 0)?', answer:'Synchronous code runs on the current call stack. After the stack clears, the runtime processes queued microtasks such as Promise reactions before moving on to timer tasks, subject to the host event-loop rules.', syntax:`console.log("A");
setTimeout(() => console.log("timer"), 0);
Promise.resolve().then(() => console.log("promise"));
console.log("B");`, output:'A, B, promise, timer (in this common browser/Node example).', tip:'Explain call stack, task queue and microtask queue rather than saying JavaScript runs everything in parallel.' },
  { topic:'C Programming', level:'Basic', title:'What is the difference between a pointer and an array?', prompt:'Explain how array names and pointer variables differ.', answer:'An array owns a fixed-size sequence of elements in its scope; a pointer is a variable that stores an address. In many expressions an array name converts to a pointer to its first element, but arrays and pointers are not interchangeable types.', syntax:`int values[] = {10, 20, 30};
int *ptr = values;
printf("%d %d\\n", values[1], *(ptr + 1));`, output:'20 20', tip:'Mention bounds, lifetime and avoiding dereferencing invalid or uninitialized pointers.' },
  { topic:'C Programming', level:'Intermediate', title:'What is dynamic memory allocation?', prompt:'Compare malloc, calloc, realloc and free.', answer:'malloc allocates uninitialized bytes; calloc allocates and zero-initializes a block; realloc changes a block size; free releases allocated storage. Check allocation results and do not use pointers after freeing them.', syntax:`size_t count = 5;
int *values = calloc(count, sizeof *values);
if (values != NULL) {
    values[0] = 42;
    free(values);
    values = NULL;
}`, output:'Allocates space for five zero-initialized integers, assigns the first, then releases it.', tip:'Avoid memory leaks, double-free, use-after-free and unchecked allocation failures.' },
  { topic:'C Programming', level:'Advanced', title:'How do you investigate undefined behavior and memory bugs?', prompt:'Describe a safe debugging workflow for a crashing C program.', answer:'Reproduce the failure, compile with strong warnings and sanitizers, inspect the stack trace, check array bounds and pointer lifetimes, then add a regression test. Undefined behavior can make results unpredictable, so do not rely on observed output.', syntax:`cc -Wall -Wextra -Wpedantic -g -fsanitize=address,undefined app.c -o app
./app`, output:'The compiler reports warnings and sanitizers can identify many invalid memory accesses and undefined operations during execution.', tip:'Sanitizers help during testing but do not prove the absence of all bugs.' },
  { topic:'HTML & CSS', level:'Basic', title:'Why use semantic HTML?', prompt:'Compare semantic elements with generic div elements.', answer:'Semantic elements such as main, nav, header, button and article communicate structure and meaning to browsers, assistive technology and developers. Use elements according to their purpose rather than styling everything with divs.', syntax:`<main>
  <article>
    <h1>Course overview</h1>
    <p>Learn the foundations.</p>
    <button type="button">Start lesson</button>
  </article>
</main>`, output:'The page exposes a meaningful document structure and a native keyboard-accessible button.', tip:'Use a real button for actions and an anchor for navigation; do not remove focus indicators without an accessible replacement.' },
  { topic:'HTML & CSS', level:'Intermediate', title:'How does CSS Flexbox differ from Grid?', prompt:'Choose a layout tool for a toolbar and a card matrix.', answer:'Flexbox is primarily one-dimensional, arranging items along a row or column. Grid handles two-dimensional row-and-column layouts. They can be combined based on the layout requirement.', syntax:`.toolbar { display: flex; gap: 1rem; align-items: center; }
.card-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem; }
@media (max-width: 700px) {
  .card-grid { grid-template-columns: 1fr; }
}`, output:'The toolbar aligns items in a row; the card layout uses three columns on wider screens and one on narrow screens.', tip:'Mention responsive behavior, minmax(0, 1fr), and avoiding fixed widths that cause overflow.' },
  { topic:'HTML & CSS', level:'Advanced', title:'How do you improve web accessibility and performance?', prompt:'Name checks you would include before shipping a responsive interface.', answer:'Use semantic markup, keyboard navigation, visible focus, sufficient contrast, labels and meaningful alt text. Optimize images, minimize render-blocking assets, reserve image dimensions, and measure real loading performance.', syntax:`<img src="/course.webp" alt="Course dashboard preview"
     width="640" height="360" loading="lazy">
<label for="email">Email</label>
<input id="email" name="email" type="email" autocomplete="email">`, output:'The image has descriptive alternative text and dimensions; the input has an explicit label and appropriate type.', tip:'Test with keyboard-only navigation and automated audits, then verify with assistive technology and real devices.' },
  { topic:'DevOps', level:'Basic', title:'What is CI/CD?', prompt:'Explain the difference between continuous integration and deployment.', answer:'Continuous integration frequently merges changes and validates them with automated checks. Continuous delivery keeps changes deployable; continuous deployment automatically releases changes that pass the pipeline to production.', syntax:`on: [push]
jobs:
  verify:
    steps:
      - run: npm ci
      - run: npm run lint
      - run: npm run build`, output:'The pipeline installs reproducible dependencies, checks code quality and produces a build artifact.', tip:'Separate build, test and deploy stages; protect production with least-privilege credentials and approvals where appropriate.' },
  { topic:'DevOps', level:'Intermediate', title:'How would you troubleshoot a failed deployment?', prompt:'Describe a structured investigation rather than retrying blindly.', answer:'Identify the failing stage, compare the deployed commit and environment, inspect logs and exit codes, verify configuration and permissions, and reproduce the build. Roll back safely if service impact is high, then add a regression check.', syntax:`git rev-parse HEAD
npm ci
npm run lint
npm run build
# Inspect deployment logs and health checks next`, output:'The commands identify the source revision and reproduce local validation; deployment-specific checks follow.', tip:'Distinguish authentication failures, authorization failures, build errors, configuration problems and application health failures.' },
  { topic:'DevOps', level:'Advanced', title:'How do you design a secure deployment pipeline?', prompt:'Discuss identity, secrets, artifacts and rollback.', answer:'Use short-lived federated identity where supported, least-privilege roles, protected branches and environments, immutable artifacts, dependency scanning, audit logs and tested rollback procedures. Never print secrets to logs.', syntax:`source commit
  -> lint + tests + security checks
  -> versioned build artifact
  -> approval / protected environment
  -> deploy with short-lived identity
  -> health check -> promote or rollback`, output:'The same validated artifact is promoted, deployment is auditable, and failed health checks trigger a controlled recovery path.', tip:'Do not give CI broad subscription or organization permissions when a resource-scoped role is sufficient.' },
  { topic:'Cloud Fundamentals', level:'Basic', title:'What are IaaS, PaaS and SaaS?', prompt:'Give an example of each service model.', answer:'IaaS provides virtualized infrastructure that customers manage further up the stack. PaaS provides a managed platform for deploying applications. SaaS delivers a complete application to end users. Exact responsibility boundaries vary by service.', syntax:`IaaS: virtual machine + customer-managed OS
PaaS: managed web app platform
SaaS: hosted email or collaboration app`, output:'The customer generally manages more of the stack in IaaS and less in PaaS and SaaS.', tip:'Explain shared responsibility; cloud does not automatically remove the need for identity, data and network security.' },
  { topic:'Cloud Fundamentals', level:'Intermediate', title:'How do regions, availability zones and scaling differ?', prompt:'Design for resilience and changing traffic.', answer:'A region is a geographic cloud area; availability zones are isolated locations within a region where supported. Scaling adds or removes capacity vertically or horizontally. High availability requires architecture, health checks, redundancy and tested recovery—not just choosing a region.', syntax:`Traffic
  -> health-checked load balancer
  -> app instances across zones
  -> managed database with backups
  -> monitoring + recovery runbook`, output:'Traffic can be routed to healthy instances, while backups and recovery procedures address data or regional failures.', tip:'Discuss recovery time objective (RTO), recovery point objective (RPO), cost and dependency failure modes.' },
  { topic:'Cloud Fundamentals', level:'Advanced', title:'How do you secure cloud workloads with least privilege?', prompt:'Explain identity, network boundaries and monitoring.', answer:'Assign workload identities instead of embedded credentials, scope roles to required resources and actions, restrict network exposure, encrypt data, rotate any necessary secrets, and monitor auditable events. Review access regularly.', syntax:`Workload identity
  -> resource-scoped role
  -> private or restricted network path
  -> encrypted data
  -> centralized logs and alerts`, output:'The workload receives only the access it needs and security events can be investigated.', tip:'Separate authentication (who/what) from authorization (which actions/resources are allowed).' },
  { topic:'Linux & Shell', level:'Basic', title:'How do you inspect files, processes and disk space?', prompt:'Name useful commands for a first-line Linux investigation.', answer:'Use pwd and ls to inspect location and files, ps or top to inspect processes, df -h for filesystem capacity, free -h for memory, and journalctl or application logs for service diagnostics. Check permissions before changing files.', syntax:`pwd
ls -lah
ps aux | head
df -h
free -h
systemctl status my-service`, output:'Displays the current directory, file details, process sample, filesystem and memory usage, and service status.', tip:'Read command output carefully and avoid destructive commands until you confirm the target path and impact.' },
  { topic:'Linux & Shell', level:'Intermediate', title:'How do pipes, redirection and exit codes work?', prompt:'Compose commands and fail a script safely.', answer:'Pipes send one command’s standard output to another command’s input. Redirection writes or reads streams. Exit status 0 conventionally means success; non-zero signals failure. Shell options can help stop a script after unexpected errors.', syntax:`#!/usr/bin/env bash
set -euo pipefail
grep -i "error" app.log | sort | uniq -c > error-counts.txt`, output:'Counts unique matching error lines and writes the summary file; with pipefail, an upstream failure can fail the pipeline.', tip:'set -e has edge cases; validate inputs and handle expected failures explicitly.' },
  { topic:'Linux & Shell', level:'Advanced', title:'How would you debug a service that cannot start?', prompt:'Cover logs, ports, permissions and dependencies.', answer:'Check systemctl status and journal logs, validate configuration, verify file ownership and permissions, inspect listening ports and dependency health, and reproduce the failure with the service’s actual user/environment. Change one thing at a time.', syntax:`systemctl status my-service
journalctl -u my-service --since "15 min ago"
ss -lntp
id service-user
`, output:'Shows service state, recent unit logs, listening TCP sockets and the current user identity (run user checks as appropriate).', tip:'Avoid exposing secrets from environment dumps or logs when sharing diagnostics.' },
  { topic:'Docker & Containers', level:'Basic', title:'What is the difference between an image and a container?', prompt:'Explain how a container is created and runs.', answer:'An image is a packaged, layered template containing application files and metadata. A container is a running or stopped instance created from an image, with its own runtime configuration and writable layer.', syntax:`docker build -t demo-app:1.0 .
docker run --rm -p 8080:8080 demo-app:1.0
docker ps`, output:'Builds an image, runs a container with a port mapping, and lists running containers.', tip:'Container isolation shares the host kernel; a container is not the same as a full virtual machine.' },
  { topic:'Docker & Containers', level:'Intermediate', title:'How do you make a Docker image smaller and safer?', prompt:'Discuss layers, multi-stage builds and non-root execution.', answer:'Use a suitable minimal base, multi-stage builds, a .dockerignore file, pinned dependencies, non-root users, and only runtime files in the final stage. Scan images and avoid secrets in build arguments or layers.', syntax:`FROM node:22-alpine AS build
WORKDIR /app
COPY package*.json ./
RUN npm ci
COPY . .
RUN npm run build

FROM nginx:alpine
COPY --from=build /app/dist /usr/share/nginx/html`, output:'The final stage contains the static build and web server, not the Node build toolchain.', tip:'Minimal images reduce attack surface but still need patching and compatibility testing.' },
  { topic:'Docker & Containers', level:'Advanced', title:'How do you troubleshoot a container that exits immediately?', prompt:'Inspect exit status, logs, configuration and health.', answer:'Check docker ps -a, inspect the exit code and container configuration, read logs, verify the command/entrypoint, required environment, mounted files and dependency connectivity. Reproduce interactively only when safe.', syntax:`docker ps -a
docker logs --tail 100 my-container
docker inspect my-container
docker run --rm --entrypoint sh demo-app:1.0`, output:'Shows stopped containers, recent logs, runtime configuration and an optional shell for investigation if the image includes one.', tip:'Do not put credentials in command-line arguments that may be recorded in shell history or process listings.' },
  { topic:'Git & GitHub', level:'Basic', title:'What is the difference between fetch, pull and clone?', prompt:'Explain how local and remote repository history is updated.', answer:'clone creates a local copy from a remote. fetch downloads remote references and objects without merging them into the current branch. pull fetches and then integrates changes, typically by merge or rebase depending on configuration.', syntax:`git clone https://github.com/example/project.git
git fetch origin
git status
git pull --ff-only origin main`, output:'Creates a clone, updates remote-tracking information, inspects the worktree and fast-forwards main if possible.', tip:'Inspect status and incoming changes before integrating, especially when the working tree has local edits.' },
  { topic:'Git & GitHub', level:'Intermediate', title:'When would you merge, rebase or cherry-pick?', prompt:'Compare common ways to integrate commits.', answer:'Merge joins histories and preserves branch structure. Rebase replays commits on a new base to create a linear history. Cherry-pick applies selected commits onto another branch. Avoid rewriting shared history without coordination.', syntax:`git fetch origin
git switch feature
git rebase origin/main
# Resolve conflicts, then:
git add <resolved-file>
git rebase --continue`, output:'Replays feature commits on top of the updated main branch after conflicts are resolved.', tip:'Use git rebase --abort if needed, and never force-push shared branches without team agreement.' },
  { topic:'Git & GitHub', level:'Advanced', title:'How do you protect a repository and its release workflow?', prompt:'Describe branch controls, secret handling and traceability.', answer:'Require reviews and status checks on protected branches, use least-privilege tokens or federated identity, scan dependencies, keep secrets out of commits, sign or verify releases where appropriate, and preserve deployment traceability.', syntax:`commit SHA
  -> required review + CI checks
  -> dependency / secret scan
  -> tagged release artifact
  -> environment-protected deployment
  -> recorded deployment result`, output:'Only reviewed and validated changes can enter the release path, and each deployment maps to a specific revision.', tip:'If a secret is committed, revoke or rotate it; deleting it from the latest file alone is not sufficient.' },
  { topic:'Kubernetes', level:'Basic', title:'What are Pods, Deployments and Services?', prompt:'Explain how an application is scheduled and reached.', answer:'A Pod is the smallest deployable unit and contains one or more containers. A Deployment manages replicated Pods and rolling updates. A Service provides a stable network endpoint for a changing set of Pods.', syntax:`kubectl get pods
kubectl get deployments
kubectl get services
kubectl describe deployment web`, output:'Lists current Pods, Deployments and Services, then shows details for the web Deployment.', tip:'Pods are replaceable; do not treat an individual Pod IP as a stable application endpoint.' },
  { topic:'Kubernetes', level:'Intermediate', title:'How do readiness, liveness and startup probes differ?', prompt:'Choose probes that help Kubernetes operate an application safely.', answer:'Readiness determines whether a Pod should receive traffic. Liveness detects a stuck process and can trigger a restart. Startup probes give slow-starting applications time before liveness checks begin. Probes should test the right failure mode.', syntax:`readinessProbe:
  httpGet:
    path: /health/ready
    port: 8080
livenessProbe:
  httpGet:
    path: /health/live
    port: 8080
  initialDelaySeconds: 10`, output:'Readiness gates traffic; liveness can restart a container when its health check repeatedly fails.', tip:'A liveness check that depends on every downstream service can cause restart loops during an external outage.' },
  { topic:'Kubernetes', level:'Advanced', title:'How do you troubleshoot a CrashLoopBackOff?', prompt:'Build a systematic diagnostic sequence.', answer:'Inspect Pod events and logs, including previous-container logs, then verify startup command, environment/configuration, secrets, resource limits, probes and dependency access. Fix the underlying cause and confirm recovery with rollout status.', syntax:`kubectl describe pod <pod-name>
kubectl logs <pod-name> --previous
kubectl get events --sort-by=.lastTimestamp
kubectl rollout status deployment/<name>`, output:'Provides Pod events, the prior failed container logs, recent events and rollout health.', tip:'Redact sensitive output before sharing logs; CrashLoopBackOff is a symptom, not the root cause.' },
  { topic:'Generative AI', level:'Basic', title:'What is the difference between a language model and a chatbot?', prompt:'Explain the model, application layer and generated output.', answer:'A language model predicts or generates text-like tokens from context. A chatbot is an application that wraps a model with instructions, conversation state, user interface and often tools or retrieval. Model output is probabilistic and can be incorrect.', syntax:`messages = [
  {"role": "system", "content": "Answer clearly and admit uncertainty."},
  {"role": "user", "content": "Explain an API in one sentence."}
]
# Send messages to a configured model provider`, output:'The application passes structured messages to a model and displays its generated response; this pseudocode does not call a provider.', tip:'Distinguish model capability from application orchestration, data access and safety controls.' },
  { topic:'Generative AI', level:'Intermediate', title:'What is RAG and when would you use it?', prompt:'Explain retrieval-augmented generation at a high level.', answer:'RAG retrieves relevant source passages for a user query and includes them in the model context. It can ground answers in current or private documents without retraining the model, but quality depends on ingestion, retrieval and source relevance.', syntax:`question -> retrieve relevant chunks
         -> build context with source metadata
         -> prompt model with question + context
         -> return answer with citations`, output:'The response is generated with retrieved context that can be cited or inspected.', tip:'Evaluate retrieval recall and answer faithfulness separately; adding more chunks can increase noise and cost.' },
  { topic:'Generative AI', level:'Advanced', title:'How do you evaluate and secure an LLM feature for production?', prompt:'Cover quality, prompt injection, privacy, latency and cost.', answer:'Create representative evaluation sets, measure task success and groundedness, test adversarial inputs, constrain tool access, minimize sensitive data, log safely, monitor latency and token cost, and provide fallback or human escalation for uncertain/high-impact cases.', syntax:`request
 -> input validation + sensitive-data policy
 -> retrieve / call model with bounded context
 -> validate structured output
 -> evaluate safety and business rules
 -> respond + record privacy-safe metrics`, output:'Only validated responses pass application checks; failures can be refused, retried safely or routed for human review.', tip:'Do not rely on the system prompt as the only security boundary.' },
  { topic:'Agentic AI', level:'Basic', title:'What makes an AI system an agent?', prompt:'Contrast a single model response with a bounded action loop.', answer:'An agent combines a model with a goal, state, tools and a control loop that can choose actions based on observations. Not every chatbot needs an agent; use tool access only when it provides a measurable benefit.', syntax:`goal = "Find the latest deployment status"
observation = read_status()
decision = model_choose_next_step(goal, observation)
# Validate the decision before any tool executes`, output:'The system observes current state, proposes a next step, and the application validates it before execution.', tip:'Keep the loop bounded by step limits, timeouts, budgets and explicit permissions.' },
  { topic:'Agentic AI', level:'Intermediate', title:'How should an agent call tools safely?', prompt:'Explain tool schemas, validation and permission checks.', answer:'Expose narrowly scoped tools with typed schemas, validate every argument, authenticate and authorize the action independently, set timeouts, and return structured results. Treat retrieved content and tool output as untrusted data.', syntax:`tool = {
  "name": "get_deployment_status",
  "arguments": {"environment": "staging"}
}
# Validate schema, authorize caller, execute read-only tool`, output:'A validated read-only request returns deployment status without granting unrelated permissions.', tip:'Never execute arbitrary model-generated shell commands or trust tool arguments without validation.' },
  { topic:'Agentic AI', level:'Advanced', title:'How do you make a multi-step agent reliable?', prompt:'Discuss retries, state, human approval and observability.', answer:'Persist explicit workflow state, make actions idempotent where possible, bound retries and budgets, define compensation for partial failure, request human approval for high-impact actions, and trace model/tool steps with privacy-safe metadata.', syntax:`plan -> validate action -> approval if required
     -> execute with timeout / idempotency key
     -> persist result
     -> verify postcondition
     -> continue or compensate`, output:'Each action has an auditable result, and the workflow can recover or pause safely after failure.', tip:'Separate model planning from deterministic policy enforcement and final authorization.' },
  { topic:'Data Engineering / Big Data', level:'Basic', title:'What are Spark, PySpark and a DataFrame?', prompt:'Explain the role of each in a data pipeline.', answer:'Apache Spark is a distributed processing engine. PySpark is its Python API. A DataFrame is a distributed table-like dataset with named columns and a schema, suitable for transformations and analytics across partitions.', syntax:`from pyspark.sql import SparkSession
spark = SparkSession.builder.appName("interview-demo").getOrCreate()
df = spark.createDataFrame([(1, "Asha"), (2, "Ravi")], ["id", "name"])
df.show()`, output:'Displays two rows with id and name columns.', tip:'Spark DataFrames are not ordinary local pandas DataFrames; execution can involve multiple executors.' },
  { topic:'Data Engineering / Big Data', level:'Intermediate', title:'What is lazy evaluation in Spark?', prompt:'Distinguish transformations from actions.', answer:'Transformations such as filter and select build a logical plan without immediately computing all results. Actions such as show, count and write trigger execution. Laziness lets Spark optimize the plan before running jobs.', syntax:`filtered = df.filter(df.id > 1).select("name")  # transformation
filtered.show()                                # action`, output:'The filter/select plan is evaluated when show() triggers execution.', tip:'Repeated actions may recompute work unless useful intermediate results are persisted appropriately.' },
  { topic:'Data Engineering / Big Data', level:'Advanced', title:'How do you diagnose a slow Spark job?', prompt:'Discuss shuffles, skew, partitions and the execution plan.', answer:'Inspect the Spark UI and explain plan, identify expensive shuffles and skewed keys, tune partition counts based on data and cluster resources, filter early, select only needed columns, and cache only reused results that fit available memory.', syntax:`df.explain("formatted")
result = (df.filter("event_date >= '2026-01-01'")
            .select("customer_id", "amount")
            .groupBy("customer_id")
            .sum("amount"))`, output:'The plan exposes logical/physical operators; the aggregation may shuffle data by customer_id.', tip:'Measure before tuning. More partitions or caching is not always faster, and skew may require a different strategy.' },
  { topic: "SQL", level: "Basic", title: "How do INNER JOIN and LEFT JOIN differ?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "INNER JOIN returns matching rows from both inputs; LEFT JOIN preserves every left-side row and fills unmatched right-side columns with NULL.", syntax: "SELECT c.id, o.id AS order_id\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id;", output: "Customers without orders still appear with a NULL order_id.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "SQL", level: "Basic", title: "What is the difference between WHERE and HAVING?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "WHERE filters rows before grouping; HAVING filters groups after GROUP BY and can use aggregate results.", syntax: "SELECT department, COUNT(*)\nFROM employees\nWHERE active = 1\nGROUP BY department\nHAVING COUNT(*) > 5;", output: "Only active employees are grouped, and only departments with more than five remain.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "SQL", level: "Basic", title: "What are primary keys, unique constraints and foreign keys?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "A primary key uniquely identifies a row and cannot be NULL. A unique constraint prevents duplicate key values. A foreign key enforces a valid relationship to referenced rows.", syntax: "CREATE TABLE orders (\n id INT PRIMARY KEY,\n customer_id INT NOT NULL REFERENCES customers(id)\n);", output: "The order has a unique identifier and must reference an existing customer.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "SQL", level: "Basic", title: "What is an index and when is it useful?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "An index is an auxiliary data structure that can speed up filtering, joins and ordering. It consumes storage and adds write overhead, so it should support real query patterns.", syntax: "CREATE INDEX idx_orders_customer\nON orders(customer_id);", output: "Queries filtering or joining by customer_id may avoid scanning every order.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "SQL", level: "Intermediate", title: "How do you use a window function to rank rows?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Window functions calculate across related rows without collapsing them like GROUP BY. PARTITION BY defines groups and ORDER BY defines sequence within each group.", syntax: "SELECT employee, department, salary,\n DENSE_RANK() OVER (PARTITION BY department ORDER BY salary DESC) AS r\nFROM employees;", output: "Each employee remains visible with a salary rank inside their department.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "SQL", level: "Intermediate", title: "How would you find duplicate records?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Group by the business key and use HAVING COUNT(*) greater than one. Inspect the rows before deleting anything and decide which record is authoritative.", syntax: "SELECT email, COUNT(*)\nFROM users\nGROUP BY email\nHAVING COUNT(*) > 1;", output: "Returns email values that occur more than once.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "SQL", level: "Intermediate", title: "What is a common table expression and why use one?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "A CTE names a query expression for readability and reuse within one statement. Recursive CTEs can traverse hierarchical data; optimizer behavior varies by database.", syntax: "WITH active_orders AS (\n SELECT * FROM orders WHERE status = 'active'\n)\nSELECT customer_id, COUNT(*)\nFROM active_orders GROUP BY customer_id;", output: "Counts active orders for each customer.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "SQL", level: "Intermediate", title: "How do you troubleshoot a slow SQL query?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Capture the actual query and representative parameters, inspect its execution plan, row estimates, scans, joins and waits, then test indexes and query rewrites against measured results.", syntax: "EXPLAIN ANALYZE\nSELECT * FROM orders WHERE customer_id = 42;", output: "The plan shows actual execution operators and timing in databases that support EXPLAIN ANALYZE.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "SQL", level: "Advanced", title: "Explain transaction isolation and common anomalies.", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Isolation controls how concurrent transactions observe each other's changes. Dirty reads, non-repeatable reads and phantom reads are possible at different isolation levels; exact behavior is engine-specific.", syntax: "BEGIN;\nSET TRANSACTION ISOLATION LEVEL SERIALIZABLE;\n-- perform related reads and writes\nCOMMIT;", output: "The transaction requests serializable isolation, subject to database implementation and possible retries.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "SQL", level: "Advanced", title: "How would you prevent lost updates in a concurrent application?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Use an atomic conditional update, optimistic version column, or appropriate row lock. Check affected-row counts and retry conflicts safely rather than relying on a read-then-write sequence.", syntax: "UPDATE inventory\nSET quantity = quantity - 1, version = version + 1\nWHERE id = 7 AND quantity > 0 AND version = 3;", output: "One affected row means the expected version and stock condition matched; zero indicates a conflict or unavailable stock.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "SQL", level: "Advanced", title: "When would you partition a large table?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Partitioning can improve manageability and enable partition pruning for queries aligned with the partition key. It does not automatically speed up every query and adds operational complexity.", syntax: "CREATE TABLE events (\n event_date DATE,\n payload TEXT\n) PARTITION BY RANGE (event_date);", output: "Rows can be routed to date ranges, allowing eligible queries to scan fewer partitions.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "SQL", level: "Advanced", title: "How do you design safe database migrations with minimal downtime?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Use backward-compatible expand-and-contract changes: add nullable/new structures, deploy code that supports both forms, backfill in batches, switch reads/writes, then remove obsolete structures after validation.", syntax: "-- Expand first\nALTER TABLE users ADD COLUMN display_name VARCHAR(120);\n-- Backfill in controlled batches; contract in a later release.", output: "Application versions can coexist during rollout while data is migrated and verified.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "REST APIs", level: "Basic", title: "What is REST and what makes an API resource-oriented?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "REST is an architectural style built around resources, representations and a uniform interface. Resource URLs identify entities while HTTP methods express operations on them.", syntax: "GET /api/v1/customers/42\nGET /api/v1/customers/42/orders", output: "The endpoints identify a customer resource and its related orders.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "REST APIs", level: "Basic", title: "Explain common HTTP methods and their intent.", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "GET retrieves a representation; POST submits data or creates subordinate resources; PUT replaces a resource; PATCH applies partial changes; DELETE removes a resource. Safe and idempotent semantics matter to clients.", syntax: "GET /users/5\nPATCH /users/5\nDELETE /users/5", output: "Each method communicates a distinct operation and expected semantics.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "REST APIs", level: "Basic", title: "What is the difference between 401 and 403?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "401 means valid authentication credentials are missing or invalid. 403 means the caller is authenticated but is not allowed to perform the requested action.", syntax: "401 Unauthorized: token missing or invalid\n403 Forbidden: user lacks required permission", output: "Clients should authenticate after 401 and not assume retrying credentials fixes a genuine 403.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "REST APIs", level: "Basic", title: "What are common HTTP status codes for APIs?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Use 2xx for success, 3xx for redirection, 4xx for client/request problems and 5xx for server failures. Choose a code that accurately describes the outcome.", syntax: "200 OK\n201 Created\n204 No Content\n400 Bad Request\n404 Not Found\n500 Internal Server Error", output: "Clients can distinguish successful creation, empty success, invalid input, missing resources and server faults.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "REST APIs", level: "Intermediate", title: "How should an API validate request data?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Validate types, required fields, formats, ranges and cross-field rules at the boundary. Return stable field-level errors and never trust client-side validation alone.", syntax: "{\n \"email\": \"not-an-email\",\n \"age\": -2\n}\n// reject with structured validation details", output: "The request is rejected before invalid values reach business logic or persistence.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "REST APIs", level: "Intermediate", title: "What is pagination and how do offset and cursor approaches differ?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Offset pagination is simple but large offsets can be expensive and concurrent inserts can shift results. Cursor pagination uses a stable ordered key and is often better for large or changing datasets.", syntax: "GET /orders?limit=20&cursor=eyJpZCI6MTAwfQ", output: "The server returns a bounded page and a continuation cursor for the next request.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "REST APIs", level: "Intermediate", title: "How do you make a POST operation idempotent?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Use an idempotency key scoped to the caller and operation, store the request outcome atomically, and return the original result for safe retries. Define expiry and conflict behavior.", syntax: "Idempotency-Key: 9f0a...\nPOST /payments", output: "A network retry with the same key does not create a second payment.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "REST APIs", level: "Intermediate", title: "How should an API handle errors consistently?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Return a stable error schema with a machine-readable code, safe message, correlation ID and optional field details. Avoid exposing stack traces, secrets or internal infrastructure information.", syntax: "{\n \"error\": {\"code\":\"VALIDATION_FAILED\", \"message\":\"Check the request\", \"traceId\":\"abc123\"}\n}", output: "Clients can display a safe message and support teams can correlate the request.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "REST APIs", level: "Advanced", title: "How do you secure an API beyond authentication?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Enforce object- and function-level authorization, validate inputs, apply rate limits, protect secrets, use TLS, constrain CORS, log security events safely and test for injection and data exposure.", syntax: "authorize(user, action, resource)\nvalidate(payload)\nrate_limit(user)\nexecute_only_if_allowed()", output: "An authenticated user can access only resources and operations they are authorized for.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "REST APIs", level: "Advanced", title: "How do you version an API without breaking clients?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Prefer additive compatible changes, publish a deprecation policy and usage telemetry, support old and new contracts during migration, and remove a version only after clients have transitioned.", syntax: "/api/v1/orders\n/api/v2/orders", output: "Both versions can coexist while consumers migrate under a communicated sunset plan.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "REST APIs", level: "Advanced", title: "How would you design rate limiting for a public API?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Choose a policy such as token bucket or sliding window, define limits by identity and route, return 429 with retry guidance, and protect shared infrastructure from distributed abuse.", syntax: "HTTP/1.1 429 Too Many Requests\nRetry-After: 30", output: "Clients can back off while the service protects capacity.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "REST APIs", level: "Advanced", title: "How do you observe and troubleshoot a production API?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Correlate structured logs, metrics and distributed traces using request IDs. Track latency percentiles, traffic, errors and saturation; separate application failures from dependency and network failures.", syntax: "request_id -> logs\ntrace_id -> spans\nmetrics: p50/p95 latency, 5xx rate, saturation", output: "An incident can be traced from client request through API code and downstream dependencies.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "C Programming", level: "Basic", title: "What is the difference between a pointer and an array?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "An array is a contiguous object containing elements; in many expressions its name converts to a pointer to its first element. A pointer is a separate variable holding an address and does not carry array length.", syntax: "int values[] = {2, 4, 6};\nint *ptr = values;\nprintf(\"%d\", ptr[1]);", output: "Prints 4; ptr points to the first element.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "C Programming", level: "Basic", title: "What is the difference between stack and heap allocation in C?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Automatic local objects commonly have block lifetime and are often stack-allocated by implementations. malloc allocates dynamic storage that remains until freed; exact physical placement is implementation-dependent.", syntax: "int local = 10;\nint *dynamic = malloc(sizeof *dynamic);\nif (dynamic) { *dynamic = 20; free(dynamic); }", output: "The dynamic allocation is released explicitly; local storage ends with its scope.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "C Programming", level: "Basic", title: "What do sizeof and strlen return?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "sizeof reports storage size in bytes for a type or object, including array capacity when applied before array-to-pointer conversion. strlen counts characters before the terminating null byte.", syntax: "char name[] = \"C\");\nprintf(\"%zu %zu\", sizeof name, strlen(name));", output: "For the corrected array declaration char name[] = \"C\", sizeof is 2 and strlen is 1.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "C Programming", level: "Basic", title: "Why must C strings end with a null character?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "C string functions use the first '\\0' byte as the end marker. A character buffer without a terminator is not a valid C string for functions such as printf with %s or strlen.", syntax: "char word[] = {'h','i','\\0'};\nprintf(\"%s\", word);", output: "Prints hi and stops at the null terminator.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "C Programming", level: "Intermediate", title: "How do malloc, calloc, realloc and free differ?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "malloc allocates uninitialized storage; calloc allocates and zero-initializes an array; realloc resizes an allocation while preserving a prefix; free releases it. Always handle allocation failure and avoid using stale pointers.", syntax: "int *items = calloc(4, sizeof *items);\nint *tmp = realloc(items, 8 * sizeof *items);\nif (tmp) items = tmp;\nfree(items);", output: "The allocation is resized safely by assigning realloc to a temporary pointer.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "C Programming", level: "Intermediate", title: "What is a memory leak and how do you find one?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "A leak occurs when allocated memory is no longer reachable but has not been freed. Use ownership conventions, cleanup paths and tools such as AddressSanitizer or Valgrind to identify leaks and invalid accesses.", syntax: "cc -g -fsanitize=address app.c -o app\n./app", output: "The sanitizer can report memory errors exercised during the run.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "C Programming", level: "Intermediate", title: "What is the difference between pass-by-value and passing a pointer?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "C passes every argument by value. Passing a pointer copies the address, allowing the function to modify the pointed-to object while the pointer argument itself remains a copy.", syntax: "void increment(int *value) { (*value)++; }\nint n = 4; increment(&n);", output: "n becomes 5 because the function writes through the copied pointer.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "C Programming", level: "Intermediate", title: "What is a struct and how can padding affect its size?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "A struct groups named members. The compiler may insert padding to satisfy alignment requirements, so sizeof a struct can exceed the sum of member sizes.", syntax: "struct Item { char flag; int count; };\nprintf(\"%zu\", sizeof(struct Item));", output: "The size includes any implementation-required padding; do not assume a fixed value across platforms.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "C Programming", level: "Advanced", title: "What is undefined behavior in C?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Undefined behavior is an operation for which the C standard imposes no requirements. Examples include signed integer overflow, out-of-bounds access and use-after-free; compilers may optimize under the assumption it does not occur.", syntax: "int values[2] = {1, 2};\n// values[2] = 3; // undefined behavior", output: "The out-of-bounds write is invalid and must be prevented.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "C Programming", level: "Advanced", title: "Explain const, volatile and restrict.", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "const prevents modification through that lvalue; volatile tells the implementation accesses are observable and should not be elided as ordinary accesses; restrict is an aliasing promise. volatile is not a thread-synchronization primitive.", syntax: "const int limit = 10;\nvolatile unsigned int *device_reg;\nvoid copy(int * restrict dst, const int * restrict src);", output: "Each qualifier expresses a different contract; none substitutes for proper atomic synchronization.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "C Programming", level: "Advanced", title: "How do function pointers work in C?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "A function pointer stores the address of a function with a compatible signature. It supports callbacks, dispatch tables and pluggable behavior; the called function must match the declared type.", syntax: "int add(int a, int b) { return a + b; }\nint (*operation)(int,int) = add;\nprintf(\"%d\", operation(2,3));", output: "Prints 5 by invoking add through a function pointer.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "C Programming", level: "Advanced", title: "How do you make C code safer for concurrent execution?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Avoid unsynchronized shared mutable state, use C atomics or platform synchronization primitives, define ownership and lifetime, and protect compound invariants with locks. Data races are undefined behavior in C.", syntax: "#include <stdatomic.h>\natomic_int counter = 0;\natomic_fetch_add(&counter, 1);", output: "The atomic increment avoids a data race on counter.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "HTML & CSS", level: "Basic", title: "What is semantic HTML and why does it matter?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Semantic elements communicate structure and meaning to browsers, assistive technologies and search engines. Use elements such as main, nav, article, button and form according to their purpose.", syntax: "<main><article><h1>Course title</h1><button>Start</button></article></main>", output: "The document exposes meaningful landmarks and native interactive behavior.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "HTML & CSS", level: "Basic", title: "When should you use class, id and data attributes?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Classes are reusable styling or scripting hooks; an id identifies one unique element in a document and can be a fragment target; data attributes store custom metadata for scripts.", syntax: "<button class=\"primary\" id=\"save\" data-action=\"save\">Save</button>", output: "CSS can target the class, a fragment can target the id, and JavaScript can read data-action.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "HTML & CSS", level: "Basic", title: "What is the CSS box model?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "The box model consists of content, padding, border and margin. With content-box, declared width excludes padding and border; border-box includes them.", syntax: "*, *::before, *::after { box-sizing: border-box; }", output: "Element sizing becomes more predictable because padding and border are included in the declared width.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "HTML & CSS", level: "Basic", title: "What is the difference between block, inline and inline-block?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Block elements generally start on a new line and accept dimensions; inline elements flow within text and ignore width/height in normal flow; inline-block flows inline but accepts box dimensions.", syntax: "span { display: inline-block; width: 8rem; }\ndiv { display: block; }", output: "The span remains in inline flow while honoring its width.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "HTML & CSS", level: "Intermediate", title: "How do Flexbox and CSS Grid differ?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Flexbox is primarily one-dimensional for arranging items along a row or column. Grid is two-dimensional and defines rows and columns together; they can be combined in one layout.", syntax: ".toolbar { display: flex; gap: 1rem; }\n.dashboard { display: grid; grid-template-columns: repeat(3, 1fr); }", output: "The toolbar lays out items along one axis; the dashboard defines a column grid.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "HTML & CSS", level: "Intermediate", title: "How do CSS specificity and the cascade work?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "The cascade considers origin, importance, layers, specificity and source order. IDs generally outrank classes, which outrank type selectors, but !important and cascade layers affect the result.", syntax: "#app .card { color: navy; }\n.card { color: gray; }", output: "The selector containing the ID wins under the same cascade origin, layer and importance.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "HTML & CSS", level: "Intermediate", title: "How do media queries support responsive design?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Media queries apply styles when viewport or device conditions match. Combine fluid sizing, flexible layouts and sensible breakpoints rather than designing for a few fixed device widths only.", syntax: "@media (max-width: 48rem) {\n .layout { grid-template-columns: 1fr; }\n}", output: "At narrow widths, the layout switches to a single column.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "HTML & CSS", level: "Intermediate", title: "How do you make a form accessible?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Associate each input with a visible label, use native controls, describe errors in text, preserve keyboard focus and group related fields with fieldset and legend. Do not rely on color alone.", syntax: "<label for=\"email\">Email</label>\n<input id=\"email\" type=\"email\" required>", output: "The input has a programmatic label and browser-native email validation.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "HTML & CSS", level: "Advanced", title: "How do you prevent layout shift and improve Core Web Vitals?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Reserve image and ad dimensions, avoid injecting content above existing content, preload critical assets carefully and measure LCP, CLS and INP with real-user data and lab diagnostics.", syntax: "img { width: 100%; aspect-ratio: 16 / 9; object-fit: cover; }", output: "The browser can reserve image space before its resource finishes loading.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "HTML & CSS", level: "Advanced", title: "What are CSS containment and content-visibility used for?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Containment limits how layout, paint and style changes affect surrounding content. content-visibility can skip rendering off-screen sections until needed, with intrinsic sizing hints to reduce layout shifts.", syntax: ".article-section { content-visibility: auto; contain-intrinsic-size: auto 40rem; }", output: "Off-screen sections can be skipped during rendering while an estimated size reserves space.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "HTML & CSS", level: "Advanced", title: "How do you structure CSS to avoid specificity conflicts?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Use component-scoped naming or modules, design tokens, low-specificity selectors and predictable layers. Avoid deeply nested selectors and widespread !important overrides.", syntax: "@layer reset, tokens, components, utilities;\n@layer components { .button { padding: .5rem 1rem; } }", output: "Layer order makes stylesheet precedence intentional and easier to maintain.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "HTML & CSS", level: "Advanced", title: "How do you handle cross-browser CSS differences?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Start with standards-based properties, progressive enhancement and feature queries. Test supported browser versions, use fallbacks for critical behavior and avoid assuming identical rendering engines.", syntax: ".card { display: flex; }\n@supports (display: grid) {\n .card { display: grid; }\n}", output: "Browsers supporting Grid use it; others retain the Flexbox fallback.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "DevOps", level: "Basic", title: "What is CI/CD?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Continuous Integration frequently merges and validates changes with automated checks. Continuous Delivery keeps software releasable; Continuous Deployment automatically releases validated changes to production.", syntax: "commit -> lint -> test -> build -> package -> deploy", output: "A change passes automated validation before it reaches an environment.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "DevOps", level: "Basic", title: "What is the difference between continuous delivery and continuous deployment?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Continuous delivery ensures a validated build can be released at any time, often with a manual approval. Continuous deployment automatically releases every qualifying change to production.", syntax: "build -> tests -> approval -> production  # delivery\nbuild -> tests -> production             # deployment", output: "The distinction is whether production release requires a manual decision.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "DevOps", level: "Basic", title: "Why should deployments use immutable artifacts?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Build once and promote the same versioned artifact through environments. Rebuilding separately can produce different dependencies or output and makes rollback less reliable.", syntax: "artifact = build(commit_sha)\npromote(artifact, \"staging\")\npromote(artifact, \"production\")", output: "Both environments receive the artifact produced from the same source revision.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "DevOps", level: "Basic", title: "What is infrastructure as code?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Infrastructure as code defines infrastructure declaratively or through code so it can be reviewed, versioned, repeated and validated. State and secrets must be handled securely.", syntax: "resource \"example\" \"service\" {\n  name = \"api\"\n}", output: "A reviewed configuration describes the intended resource rather than relying only on manual portal changes.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "DevOps", level: "Intermediate", title: "How would you design a secure CI/CD pipeline?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Use short-lived workload identity, least-privilege permissions, protected branches and environments, dependency and secret scanning, pinned actions and auditable approvals. Never print tokens in logs.", syntax: "checkout -> tests -> scan -> OIDC login\n-> deploy with scoped role", output: "The pipeline obtains short-lived credentials and deploys only after required checks.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "DevOps", level: "Intermediate", title: "How do you troubleshoot a failed deployment?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Identify the failing stage and exact revision, inspect runner logs and deployment events, verify credentials, target subscription/resource group, artifact and runtime settings, then reproduce safely and validate health after correction.", syntax: "workflow run -> failing step -> deployment logs\n-> configuration check -> redeploy -> health check", output: "The root cause is isolated to a pipeline, identity, target or application configuration issue.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "DevOps", level: "Intermediate", title: "What is blue-green deployment?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Blue-green deployment maintains two production-like environments. Traffic switches from the current blue version to the validated green version, allowing fast rollback by switching traffic back.", syntax: "deploy green -> smoke test -> switch traffic\n-> monitor -> retain blue for rollback", output: "Users are routed to green after validation; blue remains available during the rollback window.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "DevOps", level: "Intermediate", title: "How do you manage secrets in a pipeline?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Store secrets in a dedicated vault or protected secret store, prefer federated short-lived identity, scope access by environment, mask outputs and rotate exposed credentials. Avoid secrets in source, artifacts and command lines.", syntax: "pipeline -> federated identity -> secret vault\n-> retrieve only required secret at runtime", output: "The workflow accesses only the secret needed for its authorized task.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "DevOps", level: "Advanced", title: "How do you implement progressive delivery and rollback?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Release to a small cohort, evaluate health and business metrics, expand gradually, and automatically halt on defined thresholds. Keep a known-good artifact and database changes compatible with rollback.", syntax: "5% traffic -> observe error rate and latency\n-> 25% -> 100%\nif thresholds_fail: rollback", output: "Traffic expands only while service indicators remain within agreed thresholds.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "DevOps", level: "Advanced", title: "How do you reduce CI/CD supply-chain risk?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Pin third-party actions and dependencies, verify provenance and checksums, generate an SBOM, scan artifacts, protect signing keys and restrict who can publish or deploy.", syntax: "source -> pinned dependencies -> build\n-> SBOM + scan -> signed artifact -> verify at deploy", output: "The deployed artifact has traceable source and integrity evidence.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "DevOps", level: "Advanced", title: "How do you monitor deployment health?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Combine deployment annotations with request rate, error rate, latency, saturation, startup health and business checks. Compare pre- and post-release behavior and correlate incidents to a revision.", syntax: "release marker + p95 latency + 5xx rate\n+ CPU/memory + readiness", output: "A regression can be associated with the deployment and trigger rollback criteria.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "DevOps", level: "Advanced", title: "How should database changes be coordinated with zero-downtime releases?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Use expand-and-contract migrations and deploy compatible application versions. Backfill gradually, monitor locks and replication lag, switch reads after verification and remove old columns only after all consumers are updated.", syntax: "add new column -> dual write -> backfill\n-> switch reads -> stop old writes -> drop later", output: "Old and new application versions remain compatible during the migration.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Cloud Fundamentals", level: "Basic", title: "Explain IaaS, PaaS and SaaS with examples.", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "IaaS provides virtualized compute, storage and networking; PaaS manages the application runtime and platform; SaaS delivers a complete application. The provider/customer responsibility boundary differs for each.", syntax: "IaaS: virtual machine\nPaaS: managed app hosting\nSaaS: hosted email application", output: "The abstraction level and operational responsibility increase from IaaS toward SaaS.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Cloud Fundamentals", level: "Basic", title: "What is a cloud region and availability zone?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "A region is a geographic area containing cloud infrastructure. Availability zones are isolated locations within a region designed to reduce the impact of localized failures; exact guarantees vary by provider.", syntax: "region -> zone A | zone B | zone C", output: "Workloads distributed across independent zones can tolerate some zone-level failures.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Cloud Fundamentals", level: "Basic", title: "What is the shared responsibility model?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "The provider secures the underlying cloud infrastructure, while customers remain responsible for areas such as identities, data, configurations and workloads depending on the service model.", syntax: "provider: physical facilities and core infrastructure\ncustomer: access, data and workload configuration", output: "Security ownership is shared and changes with the managed service boundary.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Cloud Fundamentals", level: "Basic", title: "What is the difference between object, block and file storage?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Object storage stores objects with metadata in buckets/containers; block storage exposes volumes for disks and databases; file storage provides shared hierarchical file access over protocols such as NFS or SMB.", syntax: "object: media and backups\nblock: VM disk\nfile: shared directory", output: "Choose storage based on access pattern, latency, sharing and durability requirements.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Cloud Fundamentals", level: "Intermediate", title: "How do VPC/VNet subnets, route tables and security groups work together?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "A virtual network provides an isolated address space. Subnets divide it; route tables determine paths; firewall/security-group rules control allowed traffic. Apply least privilege and verify both directions where statefulness differs.", syntax: "client subnet -> route table -> private subnet\nallow TCP 443 only from approved source", output: "Only permitted network paths should reach the service.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Cloud Fundamentals", level: "Intermediate", title: "How do you choose between managed and self-managed databases?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Managed databases reduce operational work for patching, backups and high availability but constrain some configuration choices and add service-specific limits. Compare requirements, cost, skills and recovery needs.", syntax: "requirements -> compare operations, SLA, features\n-> estimate cost -> choose service", output: "The decision reflects total operational ownership, not just instance price.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Cloud Fundamentals", level: "Intermediate", title: "What are autoscaling and load balancing?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Load balancing distributes requests across healthy instances. Autoscaling changes capacity based on metrics or schedules. Set minimum and maximum limits, cooldowns and health checks to avoid oscillation.", syntax: "load balancer -> instance pool\nscale out when utilization exceeds threshold", output: "Traffic is spread and capacity adjusts within configured bounds.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Cloud Fundamentals", level: "Intermediate", title: "How do cloud IAM roles and policies enforce least privilege?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Policies grant specific actions on specific resources to identities or groups. Prefer roles and workload identities over shared credentials, review inherited access and audit changes regularly.", syntax: "identity -> scoped role -> resource actions", output: "The identity receives only the permissions required for its task.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Cloud Fundamentals", level: "Advanced", title: "How do you design for multi-zone high availability?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Distribute stateless compute across zones, use health-checked routing, select data replication consistent with RPO/RTO, remove single points of failure and test zone failure scenarios.", syntax: "regional endpoint -> zone A / zone B\n-> replicated data tier", output: "The service continues through a zone disruption within its defined recovery objectives.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Cloud Fundamentals", level: "Advanced", title: "How do you control cloud cost without harming reliability?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Use tagging and budgets, right-size from utilization data, scale nonproduction schedules, apply storage lifecycle policies and review data transfer. Preserve redundancy and capacity needed for SLOs.", syntax: "measure -> allocate -> optimize -> verify SLOs", output: "Savings are validated against performance, availability and recovery requirements.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Cloud Fundamentals", level: "Advanced", title: "What is disaster recovery and how do RTO and RPO differ?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "RTO is the target time to restore service; RPO is the maximum acceptable data-loss window. Choose backup, replication and failover design based on business impact, then test recovery rather than relying on documentation.", syntax: "backup + replication -> recovery environment\nRTO: restore time; RPO: data gap", output: "The recovery strategy is evaluated against explicit time and data-loss targets.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Cloud Fundamentals", level: "Advanced", title: "How would you secure a cloud-hosted application end to end?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Combine identity controls, private networking where appropriate, TLS, managed secrets, secure configuration, patching, WAF/rate limits, data encryption, logging and tested incident response.", syntax: "user -> identity + edge protection -> app\n-> private data services -> audit logs", output: "Controls protect each layer and provide evidence for detection and response.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Linux & Shell", level: "Basic", title: "How do you inspect files and directories from the shell?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Use pwd to show the current directory, ls to list entries, cd to change directories, find to search paths and stat to inspect file metadata. Quote paths containing spaces.", syntax: "pwd\nls -lah\nfind /var/log -type f -name '*.log'", output: "Shows the current path, detailed listing and matching log files.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Linux & Shell", level: "Basic", title: "How do file permissions work in Linux?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Permissions define read, write and execute for owner, group and others. Numeric modes combine bits; execute on directories controls traversal. Avoid broad permissions such as 777.", syntax: "chmod 640 app.conf\nchown app:app app.conf", output: "Owner can read/write, group can read, and others have no access.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Linux & Shell", level: "Basic", title: "How do you inspect running processes?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Use ps for a process snapshot, top or htop for live resource usage, pgrep to find processes and kill to send a signal. Identify the process before terminating it.", syntax: "ps aux | grep '[n]ginx'\npgrep -a nginx\ntop", output: "Lists matching Nginx processes and live process resource usage.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Linux & Shell", level: "Basic", title: "How do you check disk and memory usage?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "df reports filesystem capacity; du estimates directory usage; free reports memory and swap. Check inode exhaustion as well as bytes when file creation fails.", syntax: "df -h\ndf -i\ndu -sh /var/log\nfree -h", output: "Shows filesystem, inode, directory and memory utilization.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Linux & Shell", level: "Intermediate", title: "How do you troubleshoot a Linux service that will not start?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Check systemctl status and journal logs, verify unit configuration, permissions, environment files, ports and dependency availability. Correct the cause and confirm the service remains healthy after restart.", syntax: "systemctl status myapp\njournalctl -u myapp -n 100 --no-pager\nsystemctl restart myapp", output: "Provides service state, recent logs and a controlled restart.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Linux & Shell", level: "Intermediate", title: "How do pipes, redirection and exit codes work?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "A pipe connects one command's stdout to another's stdin. Redirection writes or appends streams to files. Exit code zero conventionally means success; use pipefail to catch failures within pipelines.", syntax: "set -o pipefail\ncommand_a | command_b > result.txt\nprintf 'exit=%s\\n' \"$?\"", output: "The pipeline's failure status is preserved when an earlier command fails.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Linux & Shell", level: "Intermediate", title: "How do you write a robust shell script?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Use a clear shebang, quote variable expansions, validate arguments, check command failures, use traps for cleanup and avoid parsing ls output. Handle temporary files safely.", syntax: "#!/usr/bin/env bash\nset -Eeuo pipefail\ntrap 'rm -f \"$tmp\"' EXIT", output: "The script exits on common failures and cleans up its temporary file.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Linux & Shell", level: "Intermediate", title: "How do you diagnose a port or connectivity issue?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Use ss to inspect listening sockets, getent or dig for name resolution, curl for HTTP behavior and nc for TCP reachability. Check local firewall, routes and remote security rules.", syntax: "ss -lntp\ngetent hosts example.com\ncurl -v https://example.com", output: "Separates listener, DNS, transport and HTTP-level symptoms.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Linux & Shell", level: "Advanced", title: "How do you investigate high CPU usage on a Linux host?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Identify the process and threads, inspect CPU profile or stack samples, correlate with traffic and recent changes, and distinguish user, system and I/O wait. Optimize only after locating the hot path.", syntax: "top -H\npidstat -u -p <PID> 1\nperf top", output: "Shows thread-level usage and sampled hot functions where perf is available.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Linux & Shell", level: "Advanced", title: "How do you investigate memory pressure and OOM kills?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Inspect free, vmstat and process RSS, review kernel logs for OOM events, identify leaks or oversized workloads and evaluate cgroup/container limits. Avoid assuming cache memory is automatically unavailable.", syntax: "free -h\nvmstat 1\ndmesg -T | grep -i 'out of memory'", output: "Shows memory pressure and kernel OOM evidence.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Linux & Shell", level: "Advanced", title: "How do you schedule and monitor recurring jobs?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Use systemd timers or cron with explicit environment, working directory, locking and output logging. Make jobs idempotent and alert on missed or failed executions.", syntax: "0 2 * * * /usr/local/bin/backup.sh >> /var/log/backup.log 2>&1", output: "Runs the backup daily at 02:00 and captures output for review.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Linux & Shell", level: "Advanced", title: "How do you harden SSH access on a production Linux server?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Prefer key-based authentication, disable password/root login where operationally safe, restrict network access, keep packages patched, use MFA or a bastion where supported and audit access.", syntax: "PermitRootLogin no\nPasswordAuthentication no\nPubkeyAuthentication yes", output: "SSH requires keys for login under this configuration; validate access before closing an existing session.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Docker & Containers", level: "Basic", title: "What is the difference between an image and a container?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "An image is an immutable template of filesystem layers and metadata. A container is a running or stopped instance created from an image with its own writable layer and runtime configuration.", syntax: "docker build -t demo:1 .\ndocker run --name demo demo:1", output: "Builds an image and starts a container from it.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Docker & Containers", level: "Basic", title: "What are Docker layers and why does build order matter?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Each Dockerfile instruction can create a cached layer. Put stable dependency steps before frequently changing source files to improve cache reuse, while avoiding unnecessary files in the build context.", syntax: "COPY package*.json ./\nRUN npm ci\nCOPY . .", output: "Dependency installation can be reused when only application source changes.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Docker & Containers", level: "Basic", title: "What is the purpose of EXPOSE and port publishing?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "EXPOSE documents the container port an application listens on; it does not publish it to the host. The -p option maps a host port to a container port.", syntax: "docker run -p 8080:80 nginx", output: "Host port 8080 forwards to container port 80.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Docker & Containers", level: "Basic", title: "How do you persist data beyond a container lifecycle?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Use named volumes for Docker-managed persistent data or bind mounts to connect a host path. Keep durable application data outside the container's ephemeral writable layer.", syntax: "docker volume create app-data\ndocker run -v app-data:/var/lib/app demo", output: "The named volume remains after the container is removed.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Docker & Containers", level: "Intermediate", title: "How do multi-stage Docker builds reduce image size?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Build dependencies and compile artifacts in a builder stage, then copy only runtime outputs into a smaller final base image. This reduces attack surface and shipped tooling.", syntax: "FROM node:22 AS build\nWORKDIR /app\nCOPY . .\nRUN npm ci && npm run build\nFROM nginx:alpine\nCOPY --from=build /app/dist /usr/share/nginx/html", output: "The final image contains the static build and web server, not the build toolchain.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Docker & Containers", level: "Intermediate", title: "How do Docker networks enable container communication?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Containers on a user-defined bridge network can resolve each other by name and communicate on container ports. Publish ports only when access from outside the Docker network is required.", syntax: "docker network create app-net\ndocker run -d --name db --network app-net postgres", output: "Other containers on app-net can reach the database using hostname db.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Docker & Containers", level: "Intermediate", title: "How should configuration and secrets be passed to containers?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Use environment variables or mounted configuration for nonsecret settings and a secret manager or orchestrator secret mechanism for credentials. Never bake secrets into image layers or source.", syntax: "docker run --env-file app.env demo", output: "The process receives runtime configuration; protect the env file and avoid putting secrets in image history.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Docker & Containers", level: "Intermediate", title: "How do you troubleshoot a container that exits immediately?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Inspect docker ps -a, logs and inspect output; verify entrypoint, command, environment, mounted files, permissions and process exit code. Run interactively only when safe.", syntax: "docker ps -a\ndocker logs demo\ndocker inspect demo", output: "Shows state, application output and container configuration.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Docker & Containers", level: "Advanced", title: "How do you secure a production container image?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Use minimal trusted base images, pin versions or digests, scan dependencies, run as non-root, drop capabilities, use read-only filesystems where possible and rebuild promptly for security updates.", syntax: "USER 10001:10001\nHEALTHCHECK CMD curl -f http://localhost:8080/health || exit 1", output: "The process runs without root privileges and exposes a health check.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Docker & Containers", level: "Advanced", title: "How do CPU and memory limits affect containers?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Limits constrain resource consumption through the container runtime and host kernel. Too-low limits can cause throttling or OOM kills; requests/reservations and limits have different meanings across orchestrators.", syntax: "docker run --memory=512m --cpus=1.5 demo", output: "The container is constrained to the configured memory and CPU quota.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Docker & Containers", level: "Advanced", title: "How do you reduce container startup and deployment risk?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Use deterministic builds, health checks, graceful shutdown, small images and staged rollout. Ensure the application handles SIGTERM, stops accepting new work and drains in-flight requests.", syntax: "docker stop --time 30 demo", output: "The runtime sends SIGTERM and allows up to 30 seconds before forced termination.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Docker & Containers", level: "Advanced", title: "What is the difference between bind mounts, volumes and tmpfs?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Bind mounts expose a host path; named volumes are managed by the container engine; tmpfs stores ephemeral data in memory. Select based on persistence, portability and sensitivity.", syntax: "docker run --mount type=tmpfs,destination=/tmp demo", output: "Temporary data under /tmp is held in memory and disappears with the container.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Git & GitHub", level: "Basic", title: "What is the difference between Git and GitHub?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Git is a distributed version-control system that records repository history. GitHub is a hosted collaboration platform that adds pull requests, issues, permissions, automation and repository hosting.", syntax: "git init\ngit add .\ngit commit -m \"Initial commit\"", output: "Creates a local Git repository and records a commit; GitHub can host it remotely.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Git & GitHub", level: "Basic", title: "What are the working tree, staging area and repository?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "The working tree contains checked-out files; the index/staging area records the next commit snapshot; the repository stores committed objects and history.", syntax: "git status\ngit add src/app.js\ngit diff --cached", output: "Shows changes and stages a selected file for the next commit.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Git & GitHub", level: "Basic", title: "How do branches help teams collaborate?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "A branch is a movable reference to a commit, allowing work to proceed independently before integration. Short-lived focused branches reduce merge complexity and make review easier.", syntax: "git switch -c feature/login", output: "Creates and checks out a new feature branch.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Git & GitHub", level: "Basic", title: "What is the difference between fetch, pull and push?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "fetch downloads remote refs without changing the current branch; pull fetches and integrates changes; push publishes local commits to a remote repository.", syntax: "git fetch origin\ngit pull --ff-only origin main\ngit push origin feature/login", output: "Updates remote-tracking refs, fast-forwards main when possible and publishes the feature branch.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Git & GitHub", level: "Intermediate", title: "How do you resolve a merge conflict?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Inspect conflict markers, understand both changes, edit the intended combined result, run tests, stage resolved files and complete the merge or rebase. Do not blindly accept one side.", syntax: "git status\n# edit conflicted files\ngit add src/app.js\ngit merge --continue", output: "The merge continues after the conflict is resolved and staged.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Git & GitHub", level: "Intermediate", title: "When should you use merge versus rebase?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Merge preserves the branch integration topology and creates a merge commit when needed. Rebase replays commits onto a new base for linear history; avoid rewriting shared published history without coordination.", syntax: "git fetch origin\ngit rebase origin/main", output: "Replays local commits on top of the updated main branch.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Git & GitHub", level: "Intermediate", title: "How do you safely undo a commit that has been pushed?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Use git revert to create a new commit that reverses the change without rewriting shared history. Reset is appropriate for local unpublished history when its consequences are understood.", syntax: "git revert <commit-sha>", output: "Creates a new commit that reverses the selected commit's changes.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Git & GitHub", level: "Intermediate", title: "How do you use pull requests effectively?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Keep changes focused, describe motivation and testing, request relevant reviewers, require CI and address feedback. Protect important branches from direct unreviewed pushes.", syntax: "feature branch -> pull request -> review + checks -> merge", output: "The change is reviewed and validated before integration.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Git & GitHub", level: "Advanced", title: "How do you protect a GitHub repository and its deployment workflow?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Use least-privilege teams and tokens, protected branches, required reviews and checks, secret scanning, dependency alerts and environment approvals. Prefer OIDC federation over long-lived cloud credentials.", syntax: "protected main + required CI\nGitHub OIDC -> scoped cloud role", output: "Only validated code can merge and workflows obtain short-lived deployment identity.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Git & GitHub", level: "Advanced", title: "How do you investigate a regression using Git history?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Use log, blame, diff and bisect to identify the change that introduced behavior. Reproduce with a consistent test and validate the suspected commit before reverting or fixing.", syntax: "git log --oneline -- src/\ngit bisect start\ngit bisect bad\ngit bisect good <known-good>", output: "Bisect narrows the regression to a commit based on good/bad test results.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Git & GitHub", level: "Advanced", title: "What is a signed commit and why use it?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "A cryptographic signature lets reviewers verify that a commit was signed by a trusted key or identity. Signing improves provenance but does not replace review, CI or access controls.", syntax: "git config commit.gpgsign true\ngit commit -S -m \"Change\"", output: "Git creates a signed commit when signing is configured.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Git & GitHub", level: "Advanced", title: "How do you manage large files and repository history?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Avoid committing generated artifacts and secrets, use Git LFS for suitable large binaries, and plan history rewrites carefully because they affect every clone. Rotate exposed credentials immediately.", syntax: "git lfs track \"*.psd\"\ngit add .gitattributes", output: "Matching files are stored through Git LFS when collaborators have it configured.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Kubernetes", level: "Basic", title: "What is the role of a Pod in Kubernetes?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "A Pod is the smallest deployable unit and groups one or more containers that share network identity and may share volumes. Pods are replaceable and should usually be managed by controllers.", syntax: "kubectl get pods -o wide", output: "Lists Pods and their node placement and IP addresses.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Kubernetes", level: "Basic", title: "What is the difference between a Deployment and a StatefulSet?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "A Deployment manages interchangeable stateless replicas and rollout history. A StatefulSet provides stable identities and ordered lifecycle for workloads that need persistent identity, commonly databases or clustered systems.", syntax: "kubectl get deployments,statefulsets", output: "Lists controllers with different workload semantics.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Kubernetes", level: "Basic", title: "What does a Kubernetes Service do?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "A Service provides a stable virtual endpoint for a changing set of Pods selected by labels. ClusterIP is internal; NodePort exposes a port on nodes; LoadBalancer requests an external load balancer where supported.", syntax: "kubectl expose deployment web --port=80 --target-port=8080", output: "Creates a stable Service forwarding port 80 to selected Pods on port 8080.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Kubernetes", level: "Basic", title: "What are ConfigMaps and Secrets?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "ConfigMaps hold nonconfidential configuration; Secrets hold sensitive values but require encryption at rest, access control and careful handling. Neither should be exposed broadly to workloads.", syntax: "kubectl create configmap app-config --from-literal=MODE=prod", output: "Creates a configuration entry that can be mounted or exposed to a Pod.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Kubernetes", level: "Intermediate", title: "How do readiness, liveness and startup probes differ?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Readiness controls whether traffic is sent to a Pod. Liveness detects a stuck process and can trigger restart. Startup probes protect slow-starting applications from premature liveness failures.", syntax: "readinessProbe:\n  httpGet:\n    path: /ready\n    port: 8080", output: "The Pod receives traffic only when its readiness check succeeds.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Kubernetes", level: "Intermediate", title: "How do resource requests and limits affect scheduling?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Requests inform scheduling and resource reservation. Limits cap usage for supported resources; CPU limits can throttle and memory limits can lead to OOM termination. Set values from observed workload behavior.", syntax: "resources:\n  requests: { cpu: \"250m\", memory: \"256Mi\" }\n  limits: { cpu: \"1\", memory: \"512Mi\" }", output: "The scheduler uses requests and the container is constrained by configured limits.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Kubernetes", level: "Intermediate", title: "How does Horizontal Pod Autoscaler work?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "HPA adjusts replica count based on observed metrics such as CPU utilization or custom metrics relative to targets. Metrics availability, resource requests and stabilization settings affect behavior.", syntax: "kubectl autoscale deployment web --min=2 --max=10 --cpu-percent=70", output: "Creates an autoscaler targeting 70% average CPU utilization within the replica bounds.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Kubernetes", level: "Intermediate", title: "How do you troubleshoot a Pod stuck in Pending?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Inspect describe output and events for insufficient resources, unbound PVCs, taints, affinity rules, quota or image scheduling issues. Fix the scheduling constraint and watch the Pod transition.", syntax: "kubectl describe pod <pod>\nkubectl get events --sort-by=.lastTimestamp", output: "Events usually identify why the scheduler cannot place the Pod.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Kubernetes", level: "Advanced", title: "How do NetworkPolicies restrict Pod communication?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "NetworkPolicies define allowed ingress and egress for selected Pods when the cluster network plugin enforces them. Start with a deny-by-default policy and add explicit required paths.", syntax: "apiVersion: networking.k8s.io/v1\nkind: NetworkPolicy\nspec:\n  podSelector: {}\n  policyTypes: [Ingress, Egress]", output: "Selects all Pods in the namespace and establishes policy types; rules must be added to allow required traffic.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Kubernetes", level: "Advanced", title: "How do rolling updates and rollback work?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "A Deployment gradually replaces old Pods according to maxSurge and maxUnavailable. Readiness gates traffic; rollout history supports rollback, but database and external changes must also be backward compatible.", syntax: "kubectl rollout status deployment/web\nkubectl rollout undo deployment/web", output: "Waits for rollout completion or restores the prior Deployment revision.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Kubernetes", level: "Advanced", title: "How do you secure workloads with RBAC and service accounts?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Create dedicated service accounts and bind the minimum required verbs and resources in a namespace or cluster. Avoid using default service accounts with broad permissions and audit token access.", syntax: "kubectl auth can-i get secrets --as=system:serviceaccount:app:reader", output: "Checks whether the service account is authorized to read Secrets.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Kubernetes", level: "Advanced", title: "How do you diagnose CrashLoopBackOff and OOMKilled?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Inspect current and previous logs, Pod events, exit codes, probes, resource limits and startup configuration. Distinguish application crash from kernel OOM termination and verify recovery after a targeted change.", syntax: "kubectl logs <pod> --previous\nkubectl describe pod <pod>", output: "Shows the previous container output and termination/event details.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Generative AI", level: "Basic", title: "What is a token in a language model?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "A token is a unit of text processed by a model; it may be a word, subword, character sequence or punctuation. Context windows and usage costs are often measured in tokens.", syntax: "text -> tokenizer -> token IDs -> model", output: "The tokenizer converts text into the numerical sequence consumed by the model.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Generative AI", level: "Basic", title: "What is the difference between training and inference?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Training adjusts model parameters using data and an optimization process. Inference uses a trained model to produce outputs for new inputs without updating its parameters in the ordinary serving path.", syntax: "training data -> optimization -> model weights\nprompt + weights -> generated response", output: "Training produces parameters; inference applies them to a request.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Generative AI", level: "Basic", title: "Why can a generative AI model hallucinate?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "A model generates plausible continuations based on learned patterns and context, not guaranteed facts. Missing evidence, ambiguous prompts and distribution shifts can produce confident but incorrect output.", syntax: "question -> model prediction -> verify against trusted evidence", output: "Generated text must be checked against sources or deterministic business rules.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Generative AI", level: "Basic", title: "What makes a prompt clear and useful?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "A good prompt states the task, relevant context, constraints, expected format and criteria for uncertainty. Examples can clarify the desired structure, but prompts do not replace validation.", syntax: "role + task + context + constraints + output schema", output: "The model receives explicit instructions and a defined response shape.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Generative AI", level: "Intermediate", title: "What are embeddings and how are they used in semantic search?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Embeddings map text or other inputs to numeric vectors that capture learned semantic relationships. Similarity search retrieves vectors close to a query vector, often using cosine similarity or another metric.", syntax: "query -> embedding -> nearest-neighbor search\n-> relevant document chunks", output: "Semantically related chunks can be retrieved even when exact words differ.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Generative AI", level: "Intermediate", title: "How does retrieval-augmented generation work?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "RAG retrieves relevant source chunks, adds them to the model context and asks the model to answer using that evidence. Chunking, metadata, retrieval quality and citation validation affect results.", syntax: "question -> retrieve -> rank -> context\n-> generate grounded answer -> cite sources", output: "The answer is generated with selected source material available for grounding.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Generative AI", level: "Intermediate", title: "How do temperature and top-p affect generation?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Temperature changes the sharpness of token probabilities; top-p restricts sampling to a cumulative probability mass. Lower randomness can improve consistency but does not guarantee factual accuracy.", syntax: "temperature = 0.2\n# choose top tokens within configured top_p", output: "Sampling becomes less varied, while correctness still requires evaluation.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Generative AI", level: "Intermediate", title: "How do you evaluate an LLM application?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Use representative test sets and task-specific measures such as correctness, groundedness, relevance, refusal quality, latency and cost. Combine automated scoring with human review and regression tests.", syntax: "dataset -> model run -> metric scoring\n-> human review -> regression report", output: "Evaluation compares system behavior against defined criteria.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Generative AI", level: "Advanced", title: "How do you defend a RAG application against prompt injection?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Treat retrieved documents as untrusted data, isolate instructions from content, restrict tools independently, validate outputs and enforce authorization outside the model. Test malicious instructions embedded in retrieved text.", syntax: "retrieve untrusted text -> delimit as data\n-> model -> policy validation -> allowlisted action", output: "A retrieved document cannot grant new permissions or override deterministic application policy.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Generative AI", level: "Advanced", title: "How do you protect sensitive data in an LLM pipeline?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Minimize data sent to providers, classify and redact sensitive fields, enforce tenant-level access before retrieval, configure retention appropriately and avoid logging raw prompts or outputs unnecessarily.", syntax: "authorize -> minimize/redact -> model call\n-> validate -> privacy-safe audit", output: "Only permitted, minimized context is processed and logged safely.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Generative AI", level: "Advanced", title: "How do you reduce LLM latency and cost?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Measure token counts and stage latency, cache safe repeatable outputs, reduce unnecessary context, choose suitable model sizes, stream responses and use retrieval/routing carefully. Monitor quality to avoid harmful cost optimizations.", syntax: "profile -> shorten context -> route model\n-> cache eligible result -> evaluate quality", output: "Cost and latency improve while task quality remains within acceptance criteria.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Generative AI", level: "Advanced", title: "How do you deploy an LLM feature safely?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Use staged rollout, offline evaluation, online monitoring, rate and budget limits, fallback behavior, human escalation for high-impact tasks and a rollback path for prompts, models and retrieval indexes.", syntax: "offline eval -> canary -> monitor quality/cost\n-> expand or rollback", output: "The feature is expanded only when safety and quality signals remain acceptable.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Agentic AI", level: "Basic", title: "How is an AI agent different from a chatbot?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "A chatbot primarily responds to messages; an agent can maintain state, plan steps, observe results and use tools toward a goal. Agent autonomy should be bounded by permissions and step limits.", syntax: "goal -> plan -> approved tool -> observation -> next step", output: "The agent iterates based on tool results rather than only generating a single reply.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Agentic AI", level: "Basic", title: "What is a tool in an agentic system?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "A tool is a defined function or API the model can request, such as searching documents or reading a deployment status. The application validates arguments and independently authorizes execution.", syntax: "tool schema: get_status(environment)\nvalidate -> authorize -> execute", output: "The system invokes only a well-defined permitted operation.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Agentic AI", level: "Basic", title: "Why does an agent need state or memory?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "State records task progress, observations and relevant context across steps. Persistent memory should be scoped, permission-aware, inspectable and limited to information useful for future tasks.", syntax: "task_id -> current_step + observations + results", output: "The workflow can resume without treating every prior output as trusted truth.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Agentic AI", level: "Basic", title: "What is the role of planning in an agent?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Planning decomposes a goal into smaller steps with dependencies and success criteria. Plans are provisional; the system should re-check observations and policy before each consequential action.", syntax: "goal -> ordered steps -> validate each step", output: "The agent follows a bounded plan and adapts when results differ.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Agentic AI", level: "Intermediate", title: "How should an agent validate tool arguments?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Use strict schemas, type and range checks, allowlisted identifiers and contextual authorization. Reject unexpected fields and never pass model-generated strings directly to shell or SQL execution.", syntax: "parse JSON -> schema validation -> permission check\n-> tool execution", output: "Malformed or unauthorized requests are rejected before side effects occur.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Agentic AI", level: "Intermediate", title: "How do you prevent an agent from looping indefinitely?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Set maximum steps, wall-clock timeout, token and cost budgets, repeated-action detection and explicit stop conditions. Persist progress and return a partial result when safe.", syntax: "max_steps = 8\nif repeated_state or budget_exceeded: stop", output: "The workflow terminates within defined resource and time limits.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Agentic AI", level: "Intermediate", title: "When should an agent ask for human approval?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Require approval before irreversible, external, financial, security-sensitive or user-visible actions. Show the proposed action, target, impact and evidence, then verify approval is current and scoped.", syntax: "propose action -> show details -> approval\n-> re-authorize -> execute", output: "No consequential action occurs until the authorized user approves it.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Agentic AI", level: "Intermediate", title: "How should an agent handle tool failures and retries?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Classify transient versus permanent errors, use bounded exponential backoff with jitter for safe operations, preserve idempotency and stop when retrying could duplicate side effects.", syntax: "try action with idempotency key\non transient: bounded backoff\non permanent: surface failure", output: "Retries do not silently repeat a non-idempotent action.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Agentic AI", level: "Advanced", title: "How do you design least-privilege tool access for agents?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Give each tool a narrow purpose, read-only access by default, scoped identities and explicit resource constraints. Separate planning from execution and re-check authorization at the tool boundary.", syntax: "agent -> read-only tools by default\nwrite tool -> scoped approval + authorization", output: "Compromise or prompt injection cannot grant arbitrary system access.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Agentic AI", level: "Advanced", title: "How do you make agent workflows auditable?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Record task and correlation IDs, model and prompt versions, tool names, validated arguments, approvals, results and policy decisions while redacting sensitive values. Preserve tamper-resistant logs where required.", syntax: "trace_id -> plan -> tool call -> approval\n-> result -> policy outcome", output: "Operators can reconstruct why an action was proposed and what actually ran.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Agentic AI", level: "Advanced", title: "How do you recover from partial failure in a multi-step agent?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Persist each completed step, use idempotent operations and define compensating actions for reversible side effects. Resume from verified state rather than replaying every action blindly.", syntax: "step 1 complete -> step 2 fails\n-> inspect persisted state -> compensate or resume", output: "The workflow reaches a known safe state without duplicating completed actions.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Agentic AI", level: "Advanced", title: "How do you evaluate an agent beyond answer quality?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Measure task completion, tool selection, argument correctness, policy violations, recovery, latency and cost across realistic and adversarial scenarios. Include human review for high-impact outcomes.", syntax: "scenario suite -> trace evaluation\n-> success + safety + efficiency metrics", output: "Evaluation captures both the final result and the safety of the action path.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Data Engineering / Big Data", level: "Basic", title: "What is the difference between batch and stream processing?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "Batch processing handles bounded datasets on a schedule; stream processing handles continuously arriving events with low-latency processing and state. Some systems support both modes.", syntax: "batch: daily files -> transform -> warehouse\nstream: events -> process -> sink", output: "The choice depends on freshness, volume and processing guarantees.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Data Engineering / Big Data", level: "Basic", title: "What is ETL versus ELT?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "ETL transforms data before loading it into the target; ELT loads raw or lightly processed data first and transforms within the target platform. Governance and compute capabilities influence the choice.", syntax: "ETL: extract -> transform -> load\nELT: extract -> load -> transform", output: "The transformation location differs while both produce usable datasets.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Data Engineering / Big Data", level: "Basic", title: "What is a data lake and how does it differ from a warehouse?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "A data lake stores varied raw or curated data, often in object storage and open formats. A warehouse provides managed structures and query performance for analytics; lakehouse designs combine aspects of both.", syntax: "sources -> object storage/lake -> curated tables\n-> analytics consumers", output: "Raw and curated datasets can coexist with different access patterns.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Data Engineering / Big Data", level: "Basic", title: "What is a schema and why is schema evolution important?", prompt: "Explain the concept, give a practical example, and mention a common mistake.", answer: "A schema defines field names, types and structure. Schema evolution manages compatible changes such as added or renamed columns while protecting consumers from unexpected breaking changes.", syntax: "schema v1: id, amount\nschema v2: id, amount, currency", output: "Consumers can adopt the new field through a controlled compatibility plan.", tip: "Define the concept clearly, then use the example to show when it is useful." },
  { topic: "Data Engineering / Big Data", level: "Intermediate", title: "What causes data skew in distributed processing?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Skew occurs when some partitions or keys contain far more data than others, creating straggler tasks. Diagnose partition sizes and key distributions; consider salting, repartitioning or skew-aware joins.", syntax: "df.groupBy(\"customer_id\").count().orderBy(\"count\", ascending=False)", output: "The distribution reveals heavily represented keys that may create skew.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Data Engineering / Big Data", level: "Intermediate", title: "What is the difference between repartition and coalesce in Spark?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "repartition performs a shuffle to redistribute data and can increase or decrease partitions. coalesce commonly reduces partitions with less shuffle, but may create uneven partition sizes.", syntax: "balanced = df.repartition(200)\nsmaller = balanced.coalesce(40)", output: "The first redistributes records; the second reduces partition count with less data movement.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Data Engineering / Big Data", level: "Intermediate", title: "How do you handle late-arriving events in a streaming pipeline?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Use event time rather than processing time, define watermarks and allowed lateness, and decide whether late records update, append or route to a correction stream. Monitor dropped late data.", syntax: "events.withWatermark(\"event_time\", \"15 minutes\")", output: "The engine retains event-time state within the configured lateness horizon.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Data Engineering / Big Data", level: "Intermediate", title: "How do you ensure data quality in a pipeline?", prompt: "Describe the approach, show how you would validate it, and discuss an edge case.", answer: "Validate schema, nullability, uniqueness, ranges, referential consistency and freshness. Quarantine invalid records with reasons, publish quality metrics and make retries idempotent.", syntax: "assert required_columns\ncheck_not_null(\"customer_id\")\ncheck_unique(\"event_id\")", output: "Invalid records are identified and measurable rather than silently accepted.", tip: "State your assumptions, cover failure paths and explain how you would test the behavior." },
  { topic: "Data Engineering / Big Data", level: "Advanced", title: "How do you design exactly-once or effectively-once processing?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Exactly-once requires coordinated source offsets, processing state and sink commits; many systems provide guarantees only within defined boundaries. Idempotent writes and deduplication often achieve effectively-once outcomes.", syntax: "event_id -> deduplicate\ntransactional sink commit -> checkpoint offsets", output: "A replay does not create duplicate business records when the sink enforces idempotency.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Data Engineering / Big Data", level: "Advanced", title: "How do you optimize a Spark job with expensive shuffles?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Inspect the physical plan and Spark UI, filter early, project needed columns, use appropriate partitioning, broadcast genuinely small tables and address skew. Benchmark changes on representative data.", syntax: "df.explain(\"formatted\")\nresult = large.join(broadcast(small), \"key\")", output: "The plan can use a broadcast join to avoid shuffling the large side when safe.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Data Engineering / Big Data", level: "Advanced", title: "How do you design a reliable data pipeline for retries and backfills?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Use immutable raw inputs, deterministic transformations, partitioned outputs, checkpoints and idempotent writes. Track run metadata and make backfills bounded, observable and safe alongside normal processing.", syntax: "run_id -> input partitions -> transform\n-> validate -> atomic publish", output: "A failed run can be retried or backfilled without corrupting published data.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
  { topic: "Data Engineering / Big Data", level: "Advanced", title: "How do you govern sensitive data in a lakehouse?", prompt: "Explain the production trade-offs, failure modes and how you would verify the design.", answer: "Classify datasets, enforce row/column access, mask or tokenize sensitive fields, encrypt storage and transport, track lineage and audit access. Apply retention and deletion requirements across derived datasets.", syntax: "ingest -> classify -> access policy\n-> masked views -> lineage + audit", output: "Consumers see only the data permitted by their role and purpose.", tip: "Discuss measurable requirements, security and recovery; avoid claiming a design is universally best." },
]


